'use strict';
const $ = (selector, root=document) => root.querySelector(selector);
const $$ = (selector, root=document) => [...root.querySelectorAll(selector)];
const icon = (name, cls='icon') => `<svg class="${cls}" aria-hidden="true"><use href="#${name}"/></svg>`;
const escapeHTML = value => String(value).replace(/[&<>"']/g, c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const defaultData={profile:{name:'Sandman',email:'sandman@example.com',intention:'Make space for good ideas.',avatar:'✧'},settings:{motion:true,sounds:false,enterSend:true,theme:'paper'},plugins:['research','writing'],rituals:[{id:'morning',title:'A softer start',prompt:'Gather my priorities and help me plan a thoughtful day.',time:'08:30',frequency:'Weekdays',enabled:true},{id:'inspiration',title:'A little dose of wonder',prompt:'Find a creative prompt to inspire my next project.',time:'17:00',frequency:'Every day',enabled:false}],conversations:[]};
let data;try{data={...structuredClone(defaultData),...JSON.parse(localStorage.getItem('aster-demo-v1')||'null')};}catch{data=structuredClone(defaultData);}
let page='home',transitioning=false,currentChat=null,messages=[],pendingReply=false,attachment=null,pluginFilter='All';
const homeMarkup=$('#main').innerHTML;
const pluginLibrary=[
 {id:'research',name:'The Seeker',type:'Skill',number:'I',symbol:'☉',subtitle:'Follow your curiosity.',description:'Turn a question into a thoughtful research journey. Explore ideas, compare perspectives, and collect the threads that matter.',abilities:['Explore a topic','Compare perspectives','Gather a reading list'],tag:'RESEARCH & DISCOVERY'},
 {id:'writing',name:'The Scribe',type:'Skill',number:'II',symbol:'✧',subtitle:'Give your thoughts a voice.',description:'A writing companion for the blank page. Shape a first draft, refine your voice, or find the words you have been looking for.',abilities:['Shape a first draft','Refine your voice','Write across languages'],tag:'WORDS & STORIES'},
 {id:'notion',name:'The Archivist',type:'Connector',number:'III',symbol:'◈',subtitle:'A home for every little idea.',description:'Bring your notes, knowledge, and project pages into your conversations. Keep the ideas you love within reach.',abilities:['Find saved notes','Explore project pages','Organize your knowledge'],tag:'NOTION CONNECTION'},
 {id:'browser',name:'The Navigator',type:'MCP',number:'IV',symbol:'⊹',subtitle:'Beyond the familiar horizon.',description:'A bridge between your agent and the web. Give your curiosity a wider world to wander through.',abilities:['Explore web pages','Read structured content','Navigate with context'],tag:'BROWSER TOOLS'},
 {id:'mail',name:'The Messenger',type:'Connector',number:'V',symbol:'✴',subtitle:'Make room for meaningful words.',description:'Find the conversations that matter and shape thoughtful replies with an email companion.',abilities:['Find conversations','Summarize long threads','Prepare a reply'],tag:'EMAIL CONNECTION'},
 {id:'creative',name:'The Alchemist',type:'Skill',number:'VI',symbol:'☽',subtitle:'Ordinary things. New possibilities.',description:'An unexpected angle, a new direction, a spark of something different. A creative companion for ideas still finding their shape.',abilities:['Generate creative prompts','Explore new directions','Build a concept'],tag:'CREATIVE THINKING'}
];
const seedMemories=[
 {id:'seed-1',title:'A small universe of ideas',date:'2026-09-20T10:20:00',category:'CREATIVE WANDERING',excerpt:'We followed a loose thread of an idea, and found a whole constellation. A journal, a quiet ritual, a place to begin.',messages:[{role:'user',text:'I want to build a small daily creative ritual.'},{role:'assistant',text:'Start with a page and five quiet minutes. Collect one thing you noticed, ask one unexpected question, and sketch one possibility. Your ritual can be small enough to keep and open enough to surprise you.'}]},
 {id:'seed-2',title:'The art of starting slowly',date:'2026-09-18T08:45:00',category:'EVERYDAY RITUALS',excerpt:'Making a gentle beginning.',messages:[{role:'user',text:'How can I make my mornings feel less rushed?'},{role:'assistant',text:'Choose just one small anchor: a glass of water by the window, three lines in a notebook, or a short walk. Leave a little space around it. A gentle routine grows from something you enjoy returning to.'}]},
 {id:'seed-3',title:'Somewhere between a dream & a plan',date:'2026-09-16T15:30:00',category:'NOTES & POSSIBILITIES',excerpt:'Giving a new idea somewhere to land.',messages:[{role:'user',text:'I have an idea for a personal zine, but no plan.'},{role:'assistant',text:'Let the first issue be just eight pages. Choose one feeling, collect three observations, and give each page one job. Fold a sheet of paper into a rough version before you think about polishing it.'}]},
 {id:'seed-4',title:'Little things worth keeping',date:'2026-09-12T18:10:00',category:'COLLECTED THOUGHTS',excerpt:'A place for everyday wonder.',messages:[{role:'user',text:'Help me notice more of the everyday.'},{role:'assistant',text:'Try keeping a tiny field guide to your own life. Each evening, write down one color, one sound, and one sentence you want to remember. Small observations become their own kind of map.'}]}
];
function save(){try{localStorage.setItem('aster-demo-v1',JSON.stringify(data));}catch{toast('Your browser could not save this change. It will last for this visit.');}}
function toast(message){const el=$('#toast');el.textContent=message;el.classList.add('visible');clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.classList.remove('visible'),3600);}
function formatDate(value){return new Date(value).toLocaleDateString('en-US',{month:'short',day:'2-digit',year:'numeric'});}
function allMemories(){return [...data.conversations,...seedMemories].sort((a,b)=>new Date(b.date)-new Date(a.date));}
function applyPreferences(){document.documentElement.dataset.theme=data.settings.theme;document.documentElement.classList.toggle('reduce-motion',!data.settings.motion);}
function pageHeader(kicker,title,note,action=''){return `<div class="subpage-top"><button class="back-link" data-page="home">${icon('arrow')} Back to your thoughts</button><span class="chapter-label">${kicker}</span></div><div class="subpage-heading"><div><h1>${title}</h1><p>${note}</p></div>${action}</div>`;}
function navigate(next,{replace=false}={}){if(transitioning||!['home','history','plugins','schedule','settings','profile'].includes(next))return;if(next===page)return;transitioning=true;const transition=$('#page-transition');transition.classList.add('running');const reduced=!data.settings.motion||matchMedia('(prefers-reduced-motion: reduce)').matches;setTimeout(()=>{page=next;if(!replace)history.pushState({page},'',next==='home'?'#home':`#${next}`);renderPage();window.scrollTo({top:0,behavior:'instant'});$('#main').focus({preventScroll:true});},reduced?0:370);setTimeout(()=>{transition.classList.remove('running');transitioning=false;},reduced?20:960);}
function syncGreeting(){$('#greeting-name').textContent=data.profile.name;$('.header-greeting').setAttribute('aria-label',`Hello, ${data.profile.name}. Manage your profile`);}
function renderPage(){syncGreeting();const main=$('#main');if(page==='home'){main.innerHTML=homeMarkup;initHome();}else if(page==='history')renderHistory();else if(page==='plugins')renderPlugins();else if(page==='schedule')renderSchedule();else if(page==='settings')renderSettings();else renderProfile();$$('.nav-star').forEach(el=>{el.classList.toggle('active',el.dataset.page===page);if(el.dataset.page===page)el.setAttribute('aria-current','page');else el.removeAttribute('aria-current');});}
function initHome(){$('#celestial-art').innerHTML='<img src="/assets/celestial.png" alt="A pencil-drawn constellation of orbits, tiny stars, and golden celestial bodies" />';$('#chat-form').addEventListener('submit',e=>{e.preventDefault();sendMessage();});$('#message-input').addEventListener('keydown',e=>{if(e.key==='Enter'&&!e.shiftKey&&data.settings.enterSend&&!e.isComposing){e.preventDefault();sendMessage();}});$('#message-input').addEventListener('input',e=>{e.target.style.height='auto';e.target.style.height=Math.min(e.target.scrollHeight,100)+'px';});$('#file-input').addEventListener('change',readAttachment);renderMessages();}
function renderMessages(){if(page!=='home')return;const paper=$('.conversation-paper');paper.classList.toggle('has-messages',messages.length>0||pendingReply);$('#messages').innerHTML=messages.map(m=>`<div class="message ${m.role}"><div class="message-label">${m.role==='user'?escapeHTML(data.profile.name).toUpperCase():'✧ ASTER'}</div><p>${escapeHTML(m.text)}</p></div>`).join('')+(pendingReply?'<div class="message typing"><div class="message-label">✧ ASTER</div><p aria-label="Aster is composing">···</p></div>':'');$('#messages').scrollTop=$('#messages').scrollHeight;$('.send-button').disabled=pendingReply;$('#attachment-label').textContent=attachment?attachment.name:'';}
function generateReply(text){const clean=text.toLowerCase();if(/[\u4e00-\u9fff]/.test(text))return '让我们给这个想法留一点空间。\n\n你可以先写下最想实现的一件事，再把它拆成今天就能开始的小步骤。一个问题、一页草稿、五分钟的尝试，都可以成为起点。\n\n你希望先从灵感、计划，还是整理思路开始？\n\n（这是本地演示回复，尚未连接真实 AI 服务。）';if(/[\u3040-\u30ff]/.test(text))return 'そのアイデアを、小さな一歩から育ててみましょう。まず、今日できることをひとつ書き出してみてください。\n\nこれはローカルデモのサンプル応答です。AI サービスには接続していません。';if(/\b(hola|español|gracias|ayuda)\b/.test(clean))return 'Demos un poco de espacio a esa idea. Empieza con una pregunta, una página en blanco y un pequeño paso que puedas dar hoy. ¿Qué te gustaría explorar primero?\n\nEsta es una respuesta de muestra del demo local; no hay un servicio de IA conectado.';if(/\b(bonjour|français|merci)\b/.test(clean))return 'Laissons un peu de place à cette idée. Une question, une page blanche et un petit pas suffisent pour commencer. Que souhaitez-vous explorer ?\n\nCeci est une réponse de démonstration locale, sans service IA connecté.';const suffix='\n\nA little note: this is a sample conversation in the local demo. A live AI service can be connected later.';if(/creative|unexpected|dream|idea|inspir/.test(clean))return 'Here’s a little spark: make a field guide to things that don’t have one.\n\nThe sounds of your neighborhood. The colors of a particular Tuesday. The unfinished ideas in your notebook. Choose one, collect five small observations, and turn them into a tiny zine or a visual story.\n\nWhat are you feeling curious about today?'+suffix;if(/plan|day|morning|schedule/.test(clean))return 'Let’s give your day a little room to breathe.\n\n1. Choose one thing that would make today feel meaningful.\n2. Give it a small, uninterrupted pocket of time.\n3. Leave space for a walk, a surprise, or doing nothing at all.\n\nWhat is the one thing you’d like to make room for?'+suffix;if(/tangled|untangle|clear|thought/.test(clean))return 'Put the whole tangle on the page. It doesn’t need to make sense yet.\n\nThen we can look for three threads: what you know, what you’re wondering, and what you can try next. Often, a thought only needs a little space to become a direction.\n\nWhat has been on your mind?'+suffix;return 'A thought worth sitting with. Let’s explore it a little.\n\nWhat would you like to come away with: a fresh perspective, a first draft, or a small next step? We can start wherever feels right.'+suffix;}
function persistChat(){if(!currentChat||!messages.length)return;const entry={id:currentChat,title:messages.find(m=>m.role==='user')?.text.slice(0,68)||'A new thought',date:new Date().toISOString(),category:'YOUR CONVERSATION',excerpt:messages.filter(m=>m.role==='assistant').at(-1)?.text.slice(0,170)||'A new conversation is beginning.',messages:structuredClone(messages)};data.conversations=data.conversations.filter(c=>c.id!==currentChat);data.conversations.unshift(entry);save();}
function sendMessage(){const input=$('#message-input');if(pendingReply)return;let text=input.value.trim();if(!text&&!attachment){input.focus();return;}if(attachment){text+=(text?'\n\n':'')+`[${attachment.name}]\n${attachment.text.slice(0,3000)}`;attachment=null;}if(!currentChat)currentChat='chat-'+Date.now();messages.push({role:'user',text});input.value='';input.style.height='auto';pendingReply=true;renderMessages();persistChat();setTimeout(()=>{messages.push({role:'assistant',text:generateReply(text)});pendingReply=false;persistChat();renderMessages();},950);}
function newChat(){if(pendingReply){toast('Let Aster finish this thought first.');return;}currentChat=null;messages=[];attachment=null;if(page!=='home')navigate('home');else{renderMessages();$('#message-input').value='';$('#message-input').focus();}toast('A fresh page, just for you.');}
async function readAttachment(event){const file=event.target.files[0];if(!file)return;if(file.size>100000){toast('Choose a text file smaller than 100 KB.');event.target.value='';return;}try{attachment={name:file.name,text:await file.text()};renderMessages();toast('Your note is ready to send.');}catch{toast('This file could not be read. Try another text file.');}event.target.value='';}
function renderHistory(){const memories=allMemories();$('#main').innerHTML=`<section class="page history-page">${pageHeader('CHAPTER I · MEMORIES','Thoughts, <em>worth keeping.</em>','Little postcards from everywhere your mind has wandered.',`<button class="outline-button" id="history-new">${icon('plus')} A fresh page</button>`)}<div class="history-layout"><div class="postcard-stack" style="--count:${memories.length}">${memories.map((item,i)=>`<button class="postcard ${i===0?'latest':'tucked'}" data-memory="${escapeHTML(item.id)}" style="--i:${i};--angle:${[ -2,1.7,-1.2,2.3,-.6][i%5]}deg;--shift:${[0,18,-9,12,-3][i%5]}px"><div class="postcard-meta"><span>${i===0?'YOUR MOST RECENT MEMORY':item.category}</span><span>${formatDate(item.date)}</span></div>${i===0?`<div class="postcard-stamp">${icon('star')}<span>ASTER<br>POST</span></div>`:''}<div class="postcard-content"><span class="postcard-index">N° ${String(memories.length-i).padStart(3,'0')}</span><h2>${escapeHTML(item.title)}</h2>${i===0?`<p>${escapeHTML(item.excerpt)}</p><span class="postcard-open">Pick up the thread <span>↗</span></span>`:''}</div>${i===0?'<span class="postcard-postmark">SOMEWHERE IN YOUR UNIVERSE</span>':''}</button>`).join('')}</div><aside class="history-note"><span class="hand-note">nothing good is ever lost</span><svg class="history-star"><use href="#star"/></svg><p>Some thoughts become plans.<br>Some become possibilities.<br>All of them belong here.</p><div class="history-count"><span>${String(memories.length).padStart(2,'0')}</span> memories collected</div><div class="local-note">Saved in this browser.<br>Your thoughts stay close.</div></aside></div></section>`;}
function openMemory(id){const memory=allMemories().find(m=>m.id===id);if(!memory)return;openDialog(`<div class="memory-detail"><button class="dialog-close icon-button" data-close aria-label="Close memory">${icon('close')}</button><div class="eyebrow">A POSTCARD FROM ${formatDate(memory.date).toUpperCase()}</div><h2>${escapeHTML(memory.title)}</h2><div class="memory-transcript">${memory.messages.map(m=>`<div class="message ${m.role}"><div class="message-label">${m.role==='user'?escapeHTML(data.profile.name).toUpperCase():'✧ ASTER'}</div><p>${escapeHTML(m.text)}</p></div>`).join('')}</div><button class="solid-button" data-resume="${escapeHTML(memory.id)}">Pick up the thread ${icon('arrow')}</button></div>`);}
function renderPlugins(){const filtered=pluginLibrary.filter(p=>pluginFilter==='All'||p.type===pluginFilter);$('#main').innerHTML=`<section class="page plugins-page">${pageHeader('CHAPTER II · THE ATELIER','A little <em>extra magic.</em>','New companions for your curiosity. Turn a card. Find a possibility.')}<div class="library-top"><div class="library-tabs" role="tablist" aria-label="Plugin categories">${['All','Skill','MCP','Connector'].map(tab=>`<button role="tab" aria-selected="${pluginFilter===tab}" data-filter="${tab}" class="${pluginFilter===tab?'selected':''}">${tab==='All'?'The whole collection':tab==='Skill'?'Skills':tab==='Connector'?'Connectors':'MCP tools'}</button>`).join('')}</div><span class="library-count">${data.plugins.length} companions awake</span></div><div class="tarot-grid">${filtered.map(p=>{const active=data.plugins.includes(p.id);return `<button class="tarot-item ${active?'awakened':'dormant'}" data-plugin="${p.id}" aria-label="Explore ${p.name}, ${active?'enabled':'not enabled'}"><div class="tarot-card"><div class="tarot-inner"><span class="tarot-number">${p.number}</span><span class="tarot-corner tl">✧</span><span class="tarot-corner tr">✧</span><span class="tarot-corner bl">✧</span><span class="tarot-corner br">✧</span>${active?`<div class="tarot-art"><img src="/assets/celestial.png" alt=""/><span class="tarot-symbol">${p.symbol}</span></div><span class="tarot-front-title">${p.name}</span><span class="tarot-tag">${p.tag}</span>`:`<div class="tarot-back-design"><span class="tarot-diamond"></span><span class="tarot-diamond second"></span>${icon('star')}<span class="tarot-back-orbit"></span></div><span class="tarot-back-label">A POSSIBILITY AWAITS</span><span class="tarot-back-subtitle">${p.subtitle}</span>`}</div></div><div class="tarot-caption"><div><h2>${p.name}</h2><span>${p.type}</span></div><span class="tarot-status">${active?'✧ Awake':'Turn to discover ↗'}</span></div></button>`;}).join('')}</div><div class="collection-footnote">✧ &nbsp; A collection of possibilities. Connections are simulated in this demo.</div></section>`;}
function setPluginEnabled(id, enabled){
 const plugin=pluginLibrary.find(p=>p.id===id);
 if(!plugin)throw new Error('Unknown companion.');
 if(typeof enabled!=='boolean')throw new Error('enabled must be a boolean.');
 data.plugins=enabled?[...new Set([...data.plugins,id])]:data.plugins.filter(p=>p!==id);
 save();
 if(page==='plugins')renderPlugins();
 return {id,name:plugin.name,enabled};
}
function openPlugin(id){const p=pluginLibrary.find(p=>p.id===id);if(!p)return;const active=data.plugins.includes(id);openDialog(`<div class="plugin-detail"><button class="dialog-close icon-button" data-close aria-label="Close plugin">${icon('close')}</button><div class="focused-tarot"><span class="focused-number">${p.number}</span><img src="/assets/celestial.png" alt="Celestial pencil drawing on the tarot card"/><div class="focused-title">${p.name}</div><span class="focused-type">${p.tag}</span></div><div class="plugin-detail-copy"><div class="eyebrow">${p.type.toUpperCase()} · ${active?'AWAKE':'WAITING TO AWAKEN'}</div><h2>${p.name}</h2><p class="detail-subtitle">${p.subtitle}</p><p>${p.description}</p><ul class="ability-list">${p.abilities.map(a=>`<li>${icon('star')}${a}</li>`).join('')}</ul><button class="solid-button" data-toggle-plugin="${id}">${active?'Let this card rest':'Awaken this companion'} ${icon(active?'moon':'star')}</button><p class="demo-explanation">Demo connection · No external account is accessed.</p></div></div>`);}
function renderSchedule(){$('#main').innerHTML=`<section class="page schedule-page">${pageHeader('CHAPTER III · RITUALS','Good things, <em>on repeat.</em>','A little intention, at just the right time.',`<button class="outline-button" id="create-ritual">${icon('plus')} A new ritual</button>`)}<div class="ritual-intro"><span class="ritual-clock">${icon('star')}</span><p>Leave a little something<br>for your <em>future self.</em></p><span class="hand-note">make time for what matters</span></div><div class="ritual-list">${data.rituals.length?data.rituals.map((r,i)=>`<article class="ritual-row ${r.enabled?'':'paused'}"><span class="ritual-number">${String(i+1).padStart(2,'0')}</span><div class="ritual-time">${r.time}<span>${escapeHTML(r.frequency)}</span></div><div class="ritual-copy"><h2>${escapeHTML(r.title)}</h2><p>${escapeHTML(r.prompt)}</p></div><div class="ritual-actions"><button class="switch" role="switch" aria-checked="${r.enabled}" aria-label="${r.enabled?'Pause':'Enable'} ${escapeHTML(r.title)}" data-ritual-toggle="${r.id}"><span></span></button><button class="text-button" data-ritual-edit="${r.id}">Edit ↗</button><button class="icon-button" aria-label="Delete ${escapeHTML(r.title)}" data-ritual-delete="${r.id}">${icon('trash')}</button></div></article>`).join(''):'<div class="empty-state">An open calendar. Room for a new ritual.</div>'}</div><div class="ritual-footer"><span class="hand-note">a rhythm of your own</span><p>Demo rituals are saved in this browser.<br>Scheduling is a preview; no background tasks will run.</p></div></section>`;}
function openRitual(id){const r=data.rituals.find(r=>r.id===id)||{title:'',prompt:'',time:'09:00',frequency:'Every day'};openDialog(`<form id="ritual-form" class="form-dialog" data-id="${id||''}"><button type="button" class="dialog-close icon-button" data-close aria-label="Close ritual editor">${icon('close')}</button><div class="eyebrow">A LITTLE INTENTION</div><h2>${id?'Refine your ritual.':'Begin a new ritual.'}</h2><label>Give it a name<input name="title" required maxlength="60" value="${escapeHTML(r.title)}" placeholder="A quiet moment of inspiration"/></label><label>What would you like Aster to do?<textarea name="prompt" required maxlength="500" rows="3" placeholder="Bring me a fresh creative prompt…">${escapeHTML(r.prompt)}</textarea></label><div class="form-two-col"><label>At what time?<input name="time" type="time" required value="${r.time}"/></label><label>How often?<select name="frequency">${['Every day','Weekdays','Every Monday','Every Friday'].map(f=>`<option ${r.frequency===f?'selected':''}>${f}</option>`).join('')}</select></label></div><p class="form-hint">${Intl.DateTimeFormat().resolvedOptions().timeZone} · Local demo only</p><button class="solid-button" type="submit">${id?'Save your ritual':'Make it a ritual'} ${icon('star')}</button></form>`);$('#ritual-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const title=f.get('title').trim(),prompt=f.get('prompt').trim();if(!title||!prompt){toast('Give your ritual a name and an intention.');return;}const existing=data.rituals.find(r=>r.id===id);const item={id:id||'ritual-'+Date.now(),title,prompt,time:f.get('time'),frequency:f.get('frequency'),enabled:existing?.enabled??true};if(existing)data.rituals=data.rituals.map(r=>r.id===id?item:r);else data.rituals.push(item);save();closeDialog();renderSchedule();toast('A little intention, safely kept.');});}
function renderSettings(){$('#main').innerHTML=`<section class="page settings-page">${pageHeader('CHAPTER IV · YOUR WORLD','Make yourself <em>at home.</em>','Small details. A space that feels like you.')}<div class="settings-layout"><div class="settings-main"><div class="settings-section-label">THE FEELING OF YOUR SPACE</div><div class="setting-row"><div><h2>A little movement</h2><p>Star turns, paper drifts, and artful transitions.</p></div><button class="switch" role="switch" aria-label="Interface animations" aria-checked="${data.settings.motion}" data-setting="motion"><span></span></button></div><div class="setting-row"><div><h2>Send with a keystroke</h2><p>Enter to send. Shift + Enter for a new line.</p></div><button class="switch" role="switch" aria-label="Send with Enter" aria-checked="${data.settings.enterSend}" data-setting="enterSend"><span></span></button></div><div class="setting-row appearance-row"><div><h2>The shade of your paper</h2><p>A different light for your thoughts.</p></div><div class="paper-options" aria-label="Paper appearance"><button data-theme="paper" class="paper-swatch daylight ${data.settings.theme==='paper'?'chosen':''}" aria-pressed="${data.settings.theme==='paper'}"><span></span>Daylight</button><button data-theme="dusk" class="paper-swatch dusk ${data.settings.theme==='dusk'?'chosen':''}" aria-pressed="${data.settings.theme==='dusk'}"><span></span>Twilight</button></div></div><div class="settings-section-label second">THE PERSON BEHIND THE THOUGHTS</div><button class="profile-shortcut" data-page="profile"><span class="profile-small-avatar">${data.profile.avatar}</span><span><strong>${escapeHTML(data.profile.name)}</strong><small>Your personal profile</small></span>${icon('arrow')}</button><div class="settings-section-label second">A NOTE ABOUT THIS LITTLE UNIVERSE</div><p class="settings-note">This is a local, interactive demo. Conversations, companions, rituals, and preferences are saved in this browser. No live AI service or external account is connected.</p></div><aside class="settings-aside"><img src="/assets/celestial.png" alt="A quiet constellation"/><p class="hand-note">your world, your way.</p></aside></div></section>`;}
function renderProfile(){$('#main').innerHTML=`<section class="page profile-page">${pageHeader('THE PERSON BEHIND THE THOUGHTS','Hello, <em>you.</em>','Every universe begins with someone. This one begins with you.')}<div class="profile-layout"><aside class="identity-card"><div class="identity-top">A CITIZEN OF CURIOSITY</div><div class="identity-avatar">${data.profile.avatar}</div><h2>${escapeHTML(data.profile.name)}</h2><p>${escapeHTML(data.profile.intention)}</p><div class="identity-bottom"><span>ASTER</span><span>N° 001</span></div></aside><form id="profile-form" class="profile-form"><label>What shall we call you?<input name="name" value="${escapeHTML(data.profile.name)}" required maxlength="24" placeholder="Your name"/></label><label>Your email<input type="email" name="email" value="${escapeHTML(data.profile.email)}" required maxlength="120"/></label><label>A little intention<textarea name="intention" rows="2" maxlength="120" placeholder="What brings you here?">${escapeHTML(data.profile.intention)}</textarea></label><fieldset class="avatar-picker"><legend>Choose your little symbol</legend>${['✧','☽','☉','❋'].map(a=>`<label class="avatar-option"><input type="radio" name="avatar" value="${a}" ${data.profile.avatar===a?'checked':''}/><span>${a}</span></label>`).join('')}</fieldset><button type="submit" class="solid-button">Make it yours ${icon('arrow')}</button><p class="form-hint">A local profile, saved in this browser.</p></form></div></section>`;$('#profile-form').addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);const name=f.get('name').trim();if(!name){toast('Add a name for your little universe.');return;}data.profile={name,email:f.get('email').trim(),intention:f.get('intention').trim(),avatar:f.get('avatar')};save();syncGreeting();renderProfile();toast('Your universe feels a little more like you.');});}
let dialogFocus=null;function openDialog(html){dialogFocus=document.activeElement;$('#dialog-content').innerHTML=html;const title=$('#dialog-content h2');if(title){title.id='dialog-title';$('#detail-dialog').setAttribute('aria-labelledby','dialog-title');}if(!$('#detail-dialog').open)$('#detail-dialog').showModal();}
function closeDialog(){$('#detail-dialog').close();if(dialogFocus?.isConnected)dialogFocus.focus();}
$('#detail-dialog').addEventListener('click',e=>{if(e.target===$('#detail-dialog')){const rect=e.target.getBoundingClientRect();if(e.clientX<rect.left||e.clientX>rect.right||e.clientY<rect.top||e.clientY>rect.bottom)closeDialog();}});
document.addEventListener('click',event=>{const target=event.target;const match=s=>target.closest(s);const nav=match('[data-page]');if(nav){navigate(nav.dataset.page);return;}if(match('[data-close]')){closeDialog();return;}const prompt=match('[data-prompt]');if(prompt){$('#message-input').value=prompt.dataset.prompt;$('#message-input').focus();return;}if(match('#new-chat')||match('#history-new')){newChat();return;}if(match('#attach-button')){$('#file-input').click();return;}const memory=match('[data-memory]');if(memory){openMemory(memory.dataset.memory);return;}const resume=match('[data-resume]');if(resume){if(pendingReply){toast('Let Aster finish the current thought first.');return;}const memory=allMemories().find(m=>m.id===resume.dataset.resume);currentChat=memory.id.startsWith('seed-')?'chat-'+Date.now():memory.id;messages=structuredClone(memory.messages);closeDialog();navigate('home');return;}const filter=match('[data-filter]');if(filter){pluginFilter=filter.dataset.filter;renderPlugins();return;}const plugin=match('[data-plugin]');if(plugin){openPlugin(plugin.dataset.plugin);return;}const togglePlugin=match('[data-toggle-plugin]');if(togglePlugin){const id=togglePlugin.dataset.togglePlugin,active=data.plugins.includes(id);setPluginEnabled(id,!active);openPlugin(id);toast(active?'Your companion is resting.':'A new companion joins your constellation.');return;}if(match('#create-ritual')){openRitual();return;}const edit=match('[data-ritual-edit]');if(edit){openRitual(edit.dataset.ritualEdit);return;}const toggleRitual=match('[data-ritual-toggle]');if(toggleRitual){const r=data.rituals.find(r=>r.id===toggleRitual.dataset.ritualToggle);r.enabled=!r.enabled;save();renderSchedule();toast(r.enabled?'Your ritual is awake.':'Your ritual is taking a pause.');return;}const remove=match('[data-ritual-delete]');if(remove){const id=remove.dataset.ritualDelete;data.rituals=data.rituals.filter(r=>r.id!==id);save();renderSchedule();toast('This ritual has been released.');return;}const setting=match('[data-setting]');if(setting){data.settings[setting.dataset.setting]=!data.settings[setting.dataset.setting];save();applyPreferences();renderSettings();return;}const theme=match('button[data-theme]');if(theme){data.settings.theme=theme.dataset.theme;save();applyPreferences();renderSettings();}});
window.addEventListener('popstate',()=>{const next=location.hash.slice(1)||'home';if(['home','history','plugins','schedule','settings','profile'].includes(next)){page=next;renderPage();}});
applyPreferences();page=['history','plugins','schedule','settings','profile'].includes(location.hash.slice(1))?location.hash.slice(1):'home';renderPage();

// Optional browser tools mirror the same local demo state as the interface.
if(document.modelContext?.registerTool){
 const lifecycle=new AbortController();
 const registrations=[
  {name:'list_aster_companions',title:'List Aster companions',description:'Read the six demo companions and their current local enabled state. No external accounts are accessed.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true,untrustedContentHint:false},execute(input){if(input&&Object.keys(input).length)throw new Error('This tool takes no arguments.');return pluginLibrary.map(p=>({id:p.id,name:p.name,type:p.type,enabled:data.plugins.includes(p.id)}));}},
  {name:'set_aster_companion_enabled',title:'Set local companion state',description:'Enable or disable one companion in this local demo and update the visible tarot collection. This does not connect an external account.',inputSchema:{type:'object',properties:{id:{type:'string',enum:pluginLibrary.map(p=>p.id)},enabled:{type:'boolean'}},required:['id','enabled'],additionalProperties:false},annotations:{readOnlyHint:false,untrustedContentHint:false},execute(input){if(!input||typeof input.id!=='string'||typeof input.enabled!=='boolean'||Object.keys(input).some(k=>!['id','enabled'].includes(k)))throw new Error('Provide a known companion id and a boolean enabled value.');const result=setPluginEnabled(input.id,input.enabled);page='plugins';history.replaceState({page},'','#plugins');renderPage();return result;}}
 ];
 for(const tool of registrations){try{Promise.resolve(document.modelContext.registerTool(tool,{signal:lifecycle.signal})).catch(()=>{});}catch{}}
 window.addEventListener('pagehide',()=>lifecycle.abort(),{once:true});
}
document.addEventListener('keydown',event=>{const tab=event.target.closest('[role="tab"]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(event.key)){event.preventDefault();const tabs=['All','Skill','MCP','Connector'];let index=tabs.indexOf(pluginFilter);index=event.key==='Home'?0:event.key==='End'?3:(index+(event.key==='ArrowRight'?1:3))%4;pluginFilter=tabs[index];renderPlugins();$(`[data-filter="${pluginFilter}"]`).focus();}});
